onClick:
{{
  !Input1.text || !Input3.text || !Input4.text || !Input5.text ?
    showAlert("Faltan datos obligatorios, no se puede guardar", "error") :
    Query_modal.run().then(() => {
      storeValue('id_turno_seleccionado', null); 
      closeModal('Modal1');

      // Simplemente corré la query, ella sola va a leer el valor del DatePicker1
      Query_tabla_turnos.run();

      showAlert("Guardado correctamente", "success");
    }).catch(() => {
      showAlert("Hubo un error al guardar", "error");
    })
}}
